import{_ as o,C as r,o as s,c,j as a,a as l,G as t,a2 as d}from"./chunks/framework.BgSoyxN5.js";const y=JSON.parse('{"title":"Smart Money and Insider Stock Screener | TickerForge","description":"Screen stocks using institutional fund flow, company quality, technical structure, and reported insider activity with the TickerForge Smart Money & Insider Radar.","frontmatter":{"title":"Smart Money and Insider Stock Screener | TickerForge","description":"Screen stocks using institutional fund flow, company quality, technical structure, and reported insider activity with the TickerForge Smart Money & Insider Radar.","aside":false,"outline":false,"pageClass":"smart-money-radar-page"},"headers":[],"relativePath":"smart-money-radar.md","filePath":"smart-money-radar.md","lastUpdated":1784785156000}'),h={name:"smart-money-radar.md"};function p(u,e,m,f,g,w){const i=r("TickerForgeComplianceDisclaimer"),n=r("TickerForgeSmartMoneyRadarWidget");return s(),c("div",null,[e[0]||(e[0]=a("h1",{id:"smart-money-and-insider-stock-screener",tabindex:"-1"},[l("Smart Money and Insider Stock Screener "),a("a",{class:"header-anchor",href:"#smart-money-and-insider-stock-screener","aria-label":'Permalink to "Smart Money and Insider Stock Screener"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Institutional ownership can reveal useful changes in market conviction, but raw 13F filings are difficult to compare and may arrive up to 45 days after the reporting period. TickerForge converts those filings into a structured research view, then combines them with the latest Company Decision Snapshot and reported insider activity.",-1)),t(i),e[2]||(e[2]=a("p",null,"Use the Smart Money & Insider Radar to understand how TickerForge connects fund ownership, company quality, technical structure, and reported insider activity. The public view is a working demo preview: filters and sorting change the sample, the table stays capped at 5 rows, and the real match count shows how much more is available in the full workflow.",-1)),t(n,{"api-base":"https://api.ticker-forge.com"}),e[3]||(e[3]=d('<h2 id="public-radar-vs-pro-screener" tabindex="-1">Public Radar vs Pro Screener <a class="header-anchor" href="#public-radar-vs-pro-screener" aria-label="Permalink to &quot;Public Radar vs Pro Screener&quot;">​</a></h2><p>The public radar is a free preview. It shows a 5-row sample with the same filter shape as the working screener, but not the full idea-finding workflow.</p><p>Free Stock Discovery is available as a live broad screener for business value, guarded fair value, cash flow, technical entry, and Workspace-unlocked Timing. Standard and Pro add stronger growth, quality, insider, Top Funds, and export layers.</p><p>Standard expands access to higher-score company checks and richer saved research paths. Pro access is for investors who want the real Smart Money workflow: exact sponsorship, divergence, ownership change, fund breadth, insider dollar flow, fund-position details, broader candidate coverage, signal ranking, and Excel-ready research workflows.</p><h2 id="how-to-use-the-radar" tabindex="-1">How to Use the Radar <a class="header-anchor" href="#how-to-use-the-radar" aria-label="Permalink to &quot;How to Use the Radar&quot;">​</a></h2><p>In Pro, start with <strong>Positive Flow</strong> for the broadest list of companies showing either quiet accumulation or a fund-backed rally. <strong>Quiet Accumulation</strong> focuses on cases where funds are adding before price has fully confirmed the move. <strong>Institutional Run</strong> highlights stocks where price strength and fund ownership are already moving together.</p><p><strong>High Conviction</strong> applies additional business-quality, sponsorship, and technical-structure requirements. <strong>Insider Confirmed</strong> looks for positive institutional flow alongside meaningful recent open-market insider buying. None of these labels is an automatic buy signal. They are designed to narrow a large universe into a more focused research list.</p><h2 id="what-the-public-table-shows" tabindex="-1">What the Public Table Shows <a class="header-anchor" href="#what-the-public-table-shows" aria-label="Permalink to &quot;What the Public Table Shows&quot;">​</a></h2><p>Each public row includes the company, sector, broad fund-flow direction, business label, technical setup, insider direction, and TickerForge action label. The fields that turn the preview into a working screener stay locked.</p><p>Exact sponsorship, divergence, ownership change, fund breadth, insider dollar flow, individual fund-position changes, exact insider flow, Next Step, and Excel exports remain locked. The public API applies the visible filters and sort order, but always returns only the first 5 demo rows while showing the real number of available matches.</p><p>To investigate a candidate further, open the <a href="/stock-widget">Stock Analysis Widget</a>. It adds financial details, business analysis, fund moves, insider activity, valuation context, and market conditions. Before adding a position, use <a href="/portfolio-diagnostics">Portfolio Diagnostics</a> or <a href="/import-portfolio">import your own portfolio</a> to check concentration and downside sensitivity.</p><h2 id="important-data-limitations" tabindex="-1">Important Data Limitations <a class="header-anchor" href="#important-data-limitations" aria-label="Permalink to &quot;Important Data Limitations&quot;">​</a></h2><p>Institutional data is based primarily on 13F filings and is not real-time trading data. A fund may have changed its position after the reporting date. Insider activity is based on reported Form 4 transactions and can also contain routine or low-signal activity, although TickerForge emphasizes open-market purchases and sales where possible.</p><p>Treat the Radar as a discovery tool, verify the underlying company, and consider valuation, liquidity, portfolio fit, and market regime before making a decision.</p><h2 id="screener-research-path" tabindex="-1">Screener Research Path <a class="header-anchor" href="#screener-research-path" aria-label="Permalink to &quot;Screener Research Path&quot;">​</a></h2><ul><li><p><a href="/stockdiscovery">Free Stock Discovery</a> - start with the live free screener before using deeper ownership evidence.</p></li><li><p><a href="/stock-screener">Explore the Stock Screener hub</a> — understand how this live radar fits into the broader screening workflow.</p></li><li><p><a href="/blog/fundamental-stock-screener">Fundamental Stock Screener</a> — screen for quality, valuation, cash flow, and financial strength before ownership context.</p></li><li><p><a href="/blog/momentum-stock-screener">Momentum Stock Screener</a> — screen for timing, trend, RSI, ADX, and entry setup after fundamental checks.</p></li><li><p><a href="/blog/insider-buying-screener">Insider Buying Screener</a> — learn how to separate meaningful open-market purchases from noisy Form 4 filings.</p></li><li><p><a href="/blog/ai-stock-screener">AI Stock Screener</a> — understand why AI-assisted screening still needs visible rules and diagnostics.</p></li><li><p><a href="/blog/stock-risk-screener">Stock Risk Screener</a> — screen for fragile balance sheets, volatility, and downside-warning filters.</p></li><li><p><a href="/guides/how-to-track-smart-money">How to track Smart Money</a></p></li><li><p><a href="/stock-widget">Analyze an individual stock</a></p></li><li><p><a href="/portfolio-diagnostics">Compare portfolio-level risk</a></p></li><li><p><a href="/pricing">Compare access levels</a></p></li></ul>',16))])}const b=o(h,[["render",p]]);export{y as __pageData,b as default};
